from typing import List

class Solution:
    def stringHash(self, s: str, k: int) -> str:
        n = len(s)
        result = []
        for start in range(0, n, k):
            block = s[start:start + k]
            total = sum(ord(c) - ord('a') for c in block)
            hashed_char = chr((total % 26) + ord('a'))
            result.append(hashed_char)
        return ''.join(result)

