from typing import List

MOD = 10**9 + 7
MAXL = 800

# Precompute binomial coefficients C[n][k] modulo MOD
C = [[0]*(MAXL+1) for _ in range(MAXL+1)]
for n in range(MAXL+1):
    C[n][0] = C[n][n] = 1
    for k in range(1, n):
        C[n][k] = (C[n-1][k-1] + C[n-1][k]) % MOD

# Precompute steps to reach 1 via popcount chain for every p up to MAXL
steps = [0]*(MAXL+1)  # steps[1] = 0
def popcount(x:int) -> int:
    return bin(x).count('1')

for p in range(2, MAXL+1):
    steps[p] = 1 + steps[popcount(p)]

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n_len = len(s)
        ans = 0

        # Count numbers with fewer bits than n
        for l in range(1, n_len):
            # leading bit must be 1
            for p in range(1, l+1):
                if steps[p] <= k-1:
                    ans = (ans + C[l-1][p-1]) % MOD

        # Now process numbers with same length but < n
        ones_so_far = 0
        for i, ch in enumerate(s):
            if ch == '1':
                # set this bit to 0, remaining bits arbitrary
                rem = n_len - i - 1
                # possible additional ones in remaining
                for add in range(rem+1):
                    total_ones = ones_so_far + add
                    if total_ones == 0:
                        continue  # no positive integer
                    if steps[total_ones] <= k-1:
                        ans = (ans + C[rem][add]) % MOD
                ones_so_far += 1
            # else current bit 0, continue
        # Note: we do NOT include n itself, so no need to handle it

        return ans % MOD

# Example usage:
# sol = Solution()
# print(sol.countKReducibleNumbers("111", 1))  # 3
# print(sol.countKReducibleNumbers("1000", 2))  # 6
# print(sol.countKReducibleNumbers("1", 3))  # 0
