from typing import List

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # helper to check palindrome
        def is_palindrome(x: str) -> bool:
            return x == x[::-1]

        # generate all substrings of a string (including empty)
        def substrings(st: str) -> List[str]:
            n = len(st)
            sub = ['']  # include empty substring
            for i in range(n):
                for j in range(i+1, n+1):
                    sub.append(st[i:j])
            return sub

        sub_s = substrings(s)
        sub_t = substrings(t)

        best = 0
        for ss in sub_s:
            for tt in sub_t:
                cand = ss + tt
                if len(cand) > best and is_palindrome(cand):
                    best = len(cand)
        return best

# Example usage:
# sol = Solution()
# print(sol.longestPalindrome("abcde", "ecdba"))  # Output: 5
```

