class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        vowel_idx = {'a':0,'e':1,'i':2,'o':3,'u':4}
        vowel_cnt = [0]*5
        cons_cnt = 0

        def is_all_vowels() -> bool:
            return all(c > 0 for c in vowel_cnt)

        l = 0
        r = 0
        ans = 0

        while l < n:
            # Expand r while consonant count does not exceed k
            while r < n and cons_cnt <= k:
                ch = word[r]
                if ch in vowel_idx:
                    vowel_cnt[vowel_idx[ch]] += 1
                else:
                    cons_cnt += 1
                r += 1
                if cons_cnt == k and is_all_vowels():
                    ans += 1

            # Move left boundary forward
            ch = word[l]
            if ch in vowel_idx:
                vowel_cnt[vowel_idx[ch]] -= 1
            else:
                cons_cnt -= 1
            l += 1

            # Ensure r is at least l
            if r < l:
                r = l

        return ans
