class Solution:
    def possibleStringCount(self, word: str) -> int:
        if not word:
            return 0
        ans = 1  # case of no reduction
        i = 0
        n = len(word)
        while i < n:
            j = i
            while j < n and word[j] == word[i]:
                j += 1
            length = j - i
            if length > 1:
                ans += (length - 1)
            i = j
        return ans
